SELECT 'gongkao', '宣传培训类', 'kp-ms-org-promo', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "计划组织：宣传培训类"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心战术：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "宣传要“入脑入心”，培训要“学以致用”。最忌讳走形式！"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、宣传类破题"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "别再用拉横幅、发传单这种老掉牙的招数了！"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "新媒体矩阵：利用短视频平台、微信公众号推送图文并茂的推文、甚至开发H5小游戏互动。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "结合受众特征：对老年人采用“村口大喇叭+社工上门用方言讲解”；对年轻人采用“网红达人直播带货/普法”。"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、培训类破题"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "培训决不能只是“请专家来念PPT”。"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "必须加入：【案例分析】、【实操演练】（情景模拟）、【闭卷结业考试】以及【训后的长期跟踪考核】。"}]}]}$$ AS jsonb), NULL, '宣传培训类的核心考点与高分作答技巧。', category_node.id, CAST('["面试", "计划组织", "宣传培训"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_ms_org_promo", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
